<template><div class="attach-menu-wrap"><IconButton icon="attach" label="Attach" @click="open=!open"/><div v-if="open" class="attach-popover"><IconButton icon="computer" label="From this computer" @click="computer"/><IconButton v-if="isUser" icon="documents" label="My documents" @click="$emit('documents');open=false"/></div><input ref="input" type="file" hidden multiple accept=".pdf,.png,.jpg,.jpeg,.txt,.csv" @change="choose"/></div></template>
<script setup lang="ts">import{ref}from'vue';import IconButton from'@/components/ui/IconButton.vue';defineProps<{isUser:boolean}>();const emit=defineEmits<{files:[files:File[]];documents:[]}>();const open=ref(false),input=ref<HTMLInputElement|null>(null);function computer(){open.value=false;input.value?.click()}function choose(e:Event){const el=e.target as HTMLInputElement;if(el.files?.length)emit('files',Array.from(el.files));el.value=''};</script>
